    // This code demonstrates a path traversal vulnerability where user input is directly used to construct a file path.
    public void saveFile(HttpServletRequest request) {
        String filename = request.getParameter("filename"); // User input without validation

        // Constructing the file path using unvalidated input creates a vulnerable scenario
        // allowing attackers to access files outside the intended directory (e.g., ../../../etc/passwd).
        File file = new File("/var/www/uploads/" + filename); 

        try {
            // Writing to the potentially malicious path
            file.createNewFile(); 
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
