import java.io.File;
import java.nio.file.Path;
import java.nio.file.Paths;
import javax.servlet.http.HttpServletRequest;

public class FileUploadSecure {
    // This code fixes the vulnerability by validating and sanitizing the filename before use.
    public void saveFileSecure(HttpServletRequest request) {
        String filename = request.getParameter("filename");

        // Validate that the filename contains only alphanumeric characters and underscores/dots
        if (!filename.matches("[a-zA-Z0-9._-]+")) {
            throw new IllegalArgumentException("Invalid filename");
        }

        // Use Paths.get to resolve the absolute path and ensure it stays within the target directory
        Path baseDir = Paths.get("/var/www/uploads").toAbsolutePath().normalize();
        Path filePath = baseDir.resolve(filename).normalize();

        // Ensure the resolved path starts with the base directory to prevent directory traversal
        if (!filePath.startsWith(baseDir)) {
            throw new SecurityException("Attempted path traversal detected");
        }

        try {
            File file = filePath.toFile();
            file.createNewFile();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
